sp_widget.script:
(function() {
    // RF-09/RF-17: indicadores calculados com GlideAggregate (evita GlideRecord em loop).
    var concluidos = new GlideAggregate('x_espaco_agendamento');
    concluidos.addQuery('status', 'concluido');
    concluidos.addAggregate('COUNT');
    concluidos.query();
    data.sessoesRealizadas = concluidos.next() ? parseInt(concluidos.getAggregate('COUNT'), 10) : 0;

    var ativos = new GlideAggregate('x_espaco_agendamento');
    ativos.addQuery('status', 'IN', 'novo,confirmado');
    ativos.addAggregate('COUNT');
    ativos.query();
    data.agendamentosAtivos = ativos.next() ? parseInt(ativos.getAggregate('COUNT'), 10) : 0;

    var pacotesEsgotados = new GlideAggregate('x_espaco_pacote');
    pacotesEsgotados.addQuery('status', 'esgotado');
    pacotesEsgotados.addAggregate('COUNT');
    pacotesEsgotados.query();
    data.pacotesEsgotados = pacotesEsgotados.next() ? parseInt(pacotesEsgotados.getAggregate('COUNT'), 10) : 0;

    // Faturamento: soma do preço do serviço para cada agendamento concluído.
    data.faturamento = 0;
    var gr = new GlideRecord('x_espaco_agendamento');
    gr.addQuery('status', 'concluido');
    gr.query();
    while (gr.next()) {
        data.faturamento += parseFloat(gr.servico.preco.toString() || '0');
    }

    data.ocupacao = [];
    var ga = new GlideAggregate('x_espaco_agendamento');
    ga.addQuery('status', 'concluido');
    ga.groupBy('profissional');
    ga.addAggregate('COUNT');
    ga.query();
    while (ga.next()) {
        data.ocupacao.push({
            profissional: ga.profissional.nome.toString(),
            total: parseInt(ga.getAggregate('COUNT'), 10)
        });
    }
})();
